  KEY `idx_company_id_status` (`company_id`, `status`, `up_time`),
  KEY `idx_company_kill_time` (`company_id`, `killed`, `create_time`),
  KEY `idx_kill_status_time` (`company_id`, `killed`, `status`, `up_time`),
  KEY `idx_seller_id` (`seller_id`),
  KEY `idx_supplier_id` (`supplier_user_id`),
  UNIQUE KEY `uq_sku_code_company_id` (`sku_code`, `company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商品表'
;

CREATE TABLE `demeter_goods_sale_prop` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `goods_id` bigint(20) NULL COMMENT '商品ID',
  `time_limit` varchar(32) NULL COMMENT '时效要求',
  `total_limited` int(11) NULL COMMENT '总限量',
  `single_limited` int(11) NULL COMMENT '单一限量',
  `aviable_sale_num` int(11) NULL COMMENT '可销量',
  `lock_sale_num` int(11) NULL COMMENT '冻结销量',
  `already_sale_num` int(11) NULL COMMENT '已销量',
  `sort_no` int(11) NULL COMMENT '排序号',
  `create_user_name` varchar(125) NULL COMMENT '创建人姓名',
  `create_user_id` bigint(20) NULL COMMENT '创建人ID',
  `update_user_name` varchar(125) NULL COMMENT '修改人姓名',
  `update_user_id` bigint(20) NULL COMMENT '修改人ID',
  `create_time` datetime NULL COMMENT '创建时间',
  `update_time` datetime NULL COMMENT '修改时间',
  `init_sale_num` int(11) NULL DEFAULT 0 COMMENT '初始销量',
  `company_all_area` int(11) NULL DEFAULT 1 COMMENT '是否公司全部区域可见0:否,1:是',
  `display_sale_num` int(11) NULL DEFAULT 0 COMMENT '是否显示销量:0否,1是',
  `sale_tag_id` bigint(20) NULL COMMENT '销售标签ID',
  `sale_tag_name` varchar(128) NULL COMMENT '销售标签名称',
  `total_sale_num` int(11) NULL DEFAULT 0 COMMENT '总销量',
  `goods_type` varchar(20) NULL COMMENT '商品类型',
  `after_sale_desc` text NULL COMMENT '售后描述',
  `basket_type_id` bigint(20) NULL COMMENT '框类型ID',
  `interval_status` varchar(32) NULL DEFAULT 'DISABLED' COMMENT '阶梯价状态：ENABLED开启，DISABLED关闭，默认禁用DISABLED',
  `restriction_type` int(11) NULL DEFAULT 1 COMMENT '商品限购类型 1:单一限购;2:分组限购',
  `rebate_fruit_grain_ratio` decimal(10,2) NULL COMMENT '商品返粒比例（返果粒）',
  `single_box_num` int(11) NULL COMMENT '单盒数',
  PRIMARY KEY (`id`),
  KEY `NK_goods_id_goods_type` (`goods_id`, `goods_type`),
  UNIQUE KEY `uq_goods_id` (`goods_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商品销售属性'
;

CREATE TABLE `demeter_mq_fail_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `mq_type` varchar(50) NOT NULL COMMENT 'MQ类型',
  `content` text NULL COMMENT '消息内容',
  `handle` tinyint(1) NULL DEFAULT 0 COMMENT '是否处理',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_openapi_order_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `app_id` varchar(64) NOT NULL COMMENT '应用ID(x-app-id)',
  `company_id` bigint(20) NOT NULL COMMENT '企业ID',
  `channel_order_id` varchar(64) NOT NULL COMMENT '渠道订单号(幂等键)',
  `retry_count` int(11) NOT NULL DEFAULT 1 COMMENT '序号:该channel_order_id第几次保存记录',
  `request_body` mediumtext NULL COMMENT '请求体JSON原文',
  `status` varchar(20) NOT NULL COMMENT '处理状态:SUCCESS-成功,FAIL-失败',
  `process_status` varchar(32) NOT NULL DEFAULT 'UNPROCESSED' COMMENT '处理状态:UNPROCESSED-待处理,PROCESSED-已处理',
  `error_msg` varchar(2048) NULL COMMENT '失败原因',
  `order_nos` varchar(4096) NULL COMMENT '标果内部订单号列表(JSON数组)',
  `callback_status` varchar(20) NULL COMMENT '回调状态: SUCCESS-成功, FAIL-失败, NULL-未回调',
  `enterprise_id` varchar(64) NULL COMMENT '渠道企业客户ID（请求体中的 enterpriseId）',
  `store_id` varchar(64) NULL COMMENT '渠道门店ID（请求体中的 storeId）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_app_id` (`app_id`),
  KEY `idx_channel_order_id` (`channel_order_id`),
  KEY `idx_company_id` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='开放平台订单创建日志表'
;

CREATE TABLE `demeter_operate_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `biz_no` varchar(64) NOT NULL COMMENT '业务单号',
  `biz_type` varchar(32) NOT NULL COMMENT '业务类型',
  `role` varchar(32) NULL COMMENT '操作角色',
  `action` varchar(128) NOT NULL COMMENT '动作',
  `description` varchar(128) NULL COMMENT '动作描述',
  `current_status` varchar(32) NULL COMMENT '业务单当前状态',
  `create_user_id` bigint(20) NOT NULL COMMENT '创建人id',
  `create_user_name` varchar(32) NOT NULL COMMENT '创建人姓名',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `display` tinyint(4) NOT NULL COMMENT '是否显示（1-不显示、0-显示）',
  `remark` varchar(512) NULL COMMENT '备注',
  `operate_log_no` varchar(64) NOT NULL COMMENT 'uuid',
  PRIMARY KEY (`id`),
  KEY `idx_order_no_biz_type` (`biz_no`, `biz_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='状态变更日志表'
;

CREATE TABLE `demeter_order` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_no` varchar(64) NOT NULL COMMENT '订单编号',
  `customer_id` bigint(20) NOT NULL COMMENT '下单人ID',
  `customer_name` varchar(32) NULL COMMENT '下单人姓名',
  `customer_store_id` bigint(20) NOT NULL COMMENT '下单人关联店铺ID',
  `customer_store_name` varchar(32) NULL COMMENT '下单人关联店铺名称',
  `customer_store_link_man` varchar(32) NULL COMMENT '下单人关联店铺联系人',
  `customer_store_link_phone` varchar(32) NULL COMMENT '下单人关联店铺联系电话',
  `customer_mobile` varchar(32) NULL COMMENT '下单人联系电话',
  `company_id` bigint(20) NOT NULL COMMENT '订单所属公司ID',
  `consignee_realname` varchar(32) NOT NULL COMMENT '收货人姓名',
  `consignee_telphone` varchar(32) NOT NULL COMMENT '收货人联系电话',
  `province_id` bigint(20) NOT NULL COMMENT '收货省',
  `city_id` bigint(20) NOT NULL COMMENT '收货市',
  `district_id` bigint(20) NOT NULL COMMENT '收货区',
  `street_id` bigint(20) NULL COMMENT '街道',
  `address` varchar(250) NOT NULL COMMENT '收货地址',
  `pay_type` varchar(32) NULL COMMENT '支付方式：先款、货到付款、线下支付等',
  `pay_channel` varchar(32) NOT NULL COMMENT '支付渠道',
  `order_money` decimal(12,2) NOT NULL COMMENT '订单金额',
  `discount_money` decimal(8,2) NOT NULL DEFAULT 0.00 COMMENT '优惠金额',
  `shipping_money` decimal(8,2) NOT NULL DEFAULT 0.00 COMMENT '运费金额',
  `payable_amount` decimal(12,2) NULL COMMENT '应付金额',
  `payment_amount` decimal(12,2) NULL COMMENT '实付金额',
  `shipping_sn` varchar(50) NULL COMMENT '快递、物流单号',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后修改时间',
  `statement_date` date NULL COMMENT '订单归属日期',
  `estimate_deliver_date` datetime NULL COMMENT '预计送达时间',
  `shipping_time` datetime NULL COMMENT '发货时间',
  `pay_time` datetime NULL COMMENT '支付时间',
  `receive_time` datetime NULL COMMENT '收货时间',
  `cash_date` date NULL COMMENT '提现日期',
  `status` varchar(32) NOT NULL COMMENT '订单状态',
  `remark` varchar(256) NULL COMMENT '订单备注',
  `province_name` varchar(50) NULL COMMENT '收货省名称',
  `city_name` varchar(50) NULL COMMENT '收货市名称',
  `county_name` varchar(50) NULL COMMENT '收货区名称',
  `street_name` varchar(50) NULL COMMENT '收货街道名称',
  `pay_serial_number` varchar(128) NULL COMMENT '付款流水号',
  `deleted` tinyint(4) NOT NULL DEFAULT 0 COMMENT '删除 1是 0否',
  `invite_userId` bigint(20) NULL COMMENT '下单人的邀请人id',
  `invite_user_name` varchar(32) NULL COMMENT '下单人的邀请人名称',
  `order_customer_type` varchar(32) NULL COMMENT '订单客户类型:普通、大客户',
  `loading_address` varchar(128) NULL DEFAULT '' COMMENT '装货地址或车牌号',
  `settle_remark` varchar(128) NULL COMMENT '结算备注',
  `pay_status` varchar(64) NULL COMMENT '付款状态',
  `stock_id` bigint(20) NULL COMMENT '订单所属仓库id',
  `stock_name` varchar(16) NULL COMMENT '订单所属仓库名称',
  `time_limit` tinyint(4) NULL COMMENT '订单到达时效(天)',
  `is_adjust_update` tinyint(1) NULL DEFAULT 0 COMMENT '是否有过结算调整（0--无；1--有）',
  `order_submit_record_id` bigint(20) NULL COMMENT '订单提交创建行为记录id',
  `order_source_type` varchar(32) NULL COMMENT '订单来源入口类型(普通订单、预售订单)',
  `order_marketing_type` varchar(32) NULL COMMENT '订单营销类型(VIRTUAL_COUPON_PACK/FIRST_DISCOUNT/GROUP_PRICE_DISCOUNT)',
  `seller_id` bigint(20) NULL COMMENT '卖家id',
  `is_clearing_order` tinyint(4) NULL DEFAULT 1 COMMENT '是否是清分处理订单',
  `arrears_amount` decimal(12,2) NULL COMMENT '欠款金额',
  `kpi_statement_date` date NULL COMMENT '订单业绩归属日期',
  `ext_info` text NULL COMMENT '扩展信息',
  `open_custom_fee_rules` int(11) NULL,
  PRIMARY KEY (`id`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_customer_store_id_deliver_date` (`customer_store_id`, `estimate_deliver_date`),
  KEY `idx_customer_store_id_statement_date` (`statement_date`, `customer_store_id`),
  KEY `idx_estimate_deliver_date` (`estimate_deliver_date`),
  KEY `idx_kpi_statement_date` (`kpi_statement_date`),
  UNIQUE KEY `idx_order_no` (`order_no`),
  KEY `idx_pay_type` (`pay_type`),
  KEY `idx_statement_date` (`statement_date`),
  KEY `idx_status` (`status`),
  KEY `idx_stock_id` (`stock_id`, `customer_store_id`),
  KEY `key_company_id` (`company_id`, `create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='订单主表'
;

CREATE TABLE `demeter_order_adjust_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `company_id` bigint(20) NULL COMMENT '企业ID',
  `order_id` bigint(20) NULL COMMENT '订单ID',
  `order_no` varchar(64) NULL COMMENT '订单编号',
  `adjust_reason` varchar(32) NULL COMMENT '枚举(调整原因)',
  `adjust_detail` varchar(200) NULL COMMENT '调整说明',
  `settle_info_log` mediumtext NULL COMMENT '结算信息调整前后的日志',
  `order_item_log` mediumtext NULL COMMENT '订单明细调整前后的日志',
  `create_user_id` bigint(20) NULL COMMENT '创建用户ID',
  `create_user_name` varchar(32) NULL COMMENT '创建人',
  `create_time` datetime NULL COMMENT '创建时间',
  `update_time` datetime NULL COMMENT '修改时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='订单调整日志'
;

