CREATE TABLE `demeter_order_agent_split_mode_suitable_cate` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `grid_id` bigint(20) NOT NULL COMMENT '网格id',
  `supply_batch_grid_ref_id` bigint(11) NOT NULL COMMENT '波次id',
  `split_mode` varchar(68) NOT NULL COMMENT '模式',
  `category_id` bigint(11) NOT NULL COMMENT '类目id',
  `category_level` int(11) NOT NULL COMMENT '类目级别',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '时间',
  `create_user_id` bigint(11) NOT NULL DEFAULT -1 COMMENT '创建人id',
  `create_user_name` varchar(50) NOT NULL DEFAULT 'SYSTEM' COMMENT '创建人名',
  `deleted` bigint(11) NOT NULL DEFAULT 0 COMMENT '删除',
  PRIMARY KEY (`id`),
  KEY `NK_CATE` (`deleted`, `grid_id`, `supply_batch_grid_ref_id`, `category_id`, `split_mode`),
  UNIQUE KEY `UK_CATE` (`grid_id`, `supply_batch_grid_ref_id`, `category_id`, `deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_order_agent_split_rule_batch_config` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `supply_batch_id` bigint(20) NOT NULL COMMENT '波次id',
  `grid_id` bigint(20) NOT NULL COMMENT '波次id',
  `enabled` tinyint(1) NOT NULL DEFAULT 1 COMMENT '波次id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_user_id` bigint(11) NOT NULL COMMENT '创建人id',
  `create_user_name` varchar(50) NOT NULL COMMENT '创建人name',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  `update_user_id` bigint(11) NOT NULL COMMENT '更新人id',
  `update_user_name` varchar(50) NOT NULL COMMENT '更新人name',
  `ep_entity_id` bigint(32) NOT NULL COMMENT '代理人id',
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK_GRID` (`grid_id`, `supply_batch_id`, `ep_entity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_order_cancel` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `company_id` bigint(20) NOT NULL COMMENT '省区ID',
  `order_id` bigint(20) NOT NULL COMMENT '订单ID',
  `order_no` varchar(50) NOT NULL COMMENT '订单号',
  `cancel_reason` varchar(200) NULL COMMENT '取消原因',
  `cancel_remark` varchar(500) NULL COMMENT '取消备注（选择原因是其他时填写）',
  `cancel_user_type` varchar(64) NULL COMMENT '取消用户类型（USER/STAFF）',
  `old_status` varchar(50) NULL COMMENT '取消前订单状态',
  `estimate_delivery_date` date NULL COMMENT '配送日期',
  `statement_date` date NULL COMMENT '订单归属日',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_user_id` bigint(20) NULL COMMENT '创建人ID',
  `create_user_name` varchar(50) NULL COMMENT '创建人姓名',
  PRIMARY KEY (`id`),
  KEY `nk_company_create_time` (`company_id`, `create_time`),
  KEY `nk_estimate_delivery_date` (`estimate_delivery_date`),
  KEY `nk_old_status_create_time` (`old_status`, `create_time`),
  KEY `nk_order_id` (`order_id`),
  KEY `nk_order_no` (`order_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='订单取消记录表'
;

CREATE TABLE `demeter_order_clearing` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_id` bigint(20) NOT NULL,
  `order_no` varchar(64) NULL,
  `order_payment_no` varchar(64) NULL COMMENT '订单付款单编号',
  `clearing_info` mediumtext NULL COMMENT '清分明细',
  `order_pay_title` varchar(64) NULL COMMENT '订单支付类型',
  `origin_order_payment_no` varchar(64) NULL COMMENT '原始订单付款单编号',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_order_payment_no` (`order_payment_no`),
  KEY `idx_orderid` (`order_id`),
  KEY `idx_orderid_paytitle` (`order_id`, `order_pay_title`),
  KEY `idx_orderno` (`order_no`),
  UNIQUE KEY `uk_order_payment` (`order_id`, `order_payment_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_order_clearing_commission_special_mch` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_id` bigint(20) NOT NULL,
  `order_no` varchar(64) NULL,
  `special_mch_info` mediumtext NULL COMMENT '特殊抽佣规则明细',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_orderid` (`order_id`),
  KEY `idx_orderno` (`order_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_order_clearing_temporary_record` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_id` bigint(20) NOT NULL,
  `order_no` varchar(64) NULL,
  `order_payment_no` varchar(64) NULL COMMENT '订单付款单编号',
  `clearing_info` mediumtext NULL COMMENT '清分明细',
  `order_pay_title` varchar(64) NULL COMMENT '订单支付类型',
  `origin_order_payment_no` varchar(64) NULL COMMENT '原始订单付款单编号',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_order_payment_no` (`order_payment_no`),
  KEY `idx_orderid` (`order_id`),
  KEY `idx_orderno` (`order_no`),
  KEY `idx_origin_order_payment_no` (`origin_order_payment_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_order_ext` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` bigint(20) NOT NULL COMMENT '订单ID',
  `order_no` varchar(64) NOT NULL COMMENT '订单编号',
  `seller_settlement_type` varchar(30) NOT NULL DEFAULT 'DELIVERY_DATE' COMMENT '卖家结算类型',
  `order_delivery_type` varchar(64) NOT NULL DEFAULT 'DELIVERY' COMMENT '配送类型',
  `order_channel_id` bigint(20) NULL COMMENT '订单渠道id(第三方的id)',
  `channel_id` bigint(20) NULL COMMENT '渠道id(比如335)',
  `stock_supply_batch_id` bigint(20) NULL COMMENT '下单时选择的波次ID',
  `pay_confirm_time` datetime NULL COMMENT '确认应付的时间',
  `seller_id` bigint(20) NULL COMMENT '卖家id',
  `order_type` varchar(64) NULL DEFAULT 'PHYSICAL' COMMENT '订单类型，PHYSICAL：实物订单,VIRTUAL：虚拟品订单',
  `delivery_wave_batch_id` bigint(20) NULL COMMENT '配送波次信息ID',
  `operation_user_id` bigint(20) NULL COMMENT '业务人员id',
  `delivery_wave_id` bigint(20) NULL COMMENT '配送波次',
  `payable_confirm_money_operation` bit(1) NULL COMMENT '确认应付款资金操作状态',
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_channel_id_uk` (`order_channel_id`),
  UNIQUE KEY `order_id_uk` (`order_id`),
  UNIQUE KEY `order_no_uk` (`order_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_order_ext_fee` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `ext_fee_status` varchar(255) NOT NULL COMMENT '扩展费用状态',
  `ext_fee_amount` decimal(8,2) NOT NULL DEFAULT 0.00 COMMENT '扩展费用金额',
  `fee_type` varchar(255) NOT NULL COMMENT '费用类型',
  `company_id` bigint(20) NOT NULL COMMENT '订单所属公司ID',
  `customer_store_id` bigint(20) NOT NULL COMMENT '下单人关联店铺ID',
  `customer_store_name` varchar(32) NOT NULL COMMENT '下单人关联店铺名称',
  `bind_order_id` bigint(20) NULL COMMENT '绑定的订单id',
  `pay_status` varchar(64) NULL COMMENT '付款状态',
  `pay_serial_number` varchar(128) NULL COMMENT '付款流水号',
  `order_submit_record_id` bigint(20) NULL COMMENT '订单提交创建行为记录id',
  `pay_time` datetime NULL COMMENT '支付时间',
  `statement_date` date NULL COMMENT '订单归属日期',
  `estimate_deliver_date` date NULL COMMENT '预计送达时间',
  `ext_info` text NULL COMMENT '扩展信息',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后修改时间',
  `change_in_ordering` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否是在下单的时候收取',
  `insert_version` varchar(68) NULL COMMENT '费用版本',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_normal` (`customer_store_id`, `estimate_deliver_date`, `company_id`, `fee_type`),
  KEY `idx_statement_date` (`statement_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_order_fee` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_id` bigint(20) NOT NULL COMMENT '订单id',
  `order_no` varchar(64) NOT NULL COMMENT '订单编号',
  `fee_type` varchar(64) NOT NULL COMMENT '费用类型',
  `amount` decimal(12,2) NOT NULL COMMENT '费用金额',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `extinfo` text NULL COMMENT '其他信息',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`),
  UNIQUE KEY `idx_order_id_fee` (`order_id`, `fee_type`),
  KEY `idx_order_no` (`order_no`),
  KEY `idx_orderid_amount_feetype` (`order_id`, `amount`, `fee_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_order_fee_clearing_rule` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `company_id` bigint(20) NOT NULL COMMENT '公司ID',
  `stock_id` bigint(20) NOT NULL COMMENT '配送仓',
  `province_id` bigint(20) NULL COMMENT '省',
  `city_id` bigint(20) NULL COMMENT '市',
  `district_id` bigint(20) NULL COMMENT '区',
  `order_fee_type` varchar(64) NOT NULL COMMENT '订单费用类型',
  `purchase_myself` tinyint(4) NOT NULL DEFAULT 0 COMMENT '供应商自采SKU',
  `distribution_account_type` varchar(64) NULL COMMENT '分账方账户类型',
  `distribution_account_id` bigint(20) NULL COMMENT '分账方账户',
  `distribution_account_name` varchar(64) NULL COMMENT '分账账户名',
  `distribution_ratio` int(11) NULL COMMENT '分账比率',
  `settlement_delay_day` int(11) NULL COMMENT '结算延后多少天',
  `settlement_cycle_of_month` int(11) NULL COMMENT '每个月的几号可以结算',
  `clearing_type` varchar(20) NOT NULL DEFAULT 'FIXED_RATIO' COMMENT '清分类型：固定比例FIXED_RATIO/固定费率FIXED_RATE',
  `share_rate` decimal(12,4) NOT NULL DEFAULT 0.0000 COMMENT '分账费率',
  `priority` int(11) NOT NULL DEFAULT 0 COMMENT '优先级，值越小优先级越高',
  PRIMARY KEY (`id`),
  KEY `bus_index` (`stock_id`, `province_id`, `city_id`, `district_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_order_grid_batch_daily_weight_reduce` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `statement_data` date NOT NULL COMMENT '结算时间',
  `weight_sum` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT '重量合计',
  `grid_id` bigint(20) NOT NULL COMMENT '网格id',
  `batch_id` bigint(20) NOT NULL COMMENT '波次id',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK_GRID_BATCH_TIME` (`grid_id`, `batch_id`, `statement_data`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='订单网格批次重量聚合表'
;

CREATE TABLE `demeter_order_grid_batch_daily_weight_reduce_record` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `order_id` bigint(20) NOT NULL COMMENT '订单id',
  `event_type` varchar(50) NOT NULL COMMENT '事件类型',
  `weight` bigint(20) NOT NULL COMMENT '网格id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK_ORDER_EVENT_TYPE` (`order_id`, `event_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='订单网格批次重量聚合表明细表'
;

CREATE TABLE `demeter_order_intercept` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `intercept_no` varchar(255) NULL COMMENT '拦截单号',
  `order_id` bigint(20) NULL COMMENT '订单ID',
  `order_no` varchar(255) NULL COMMENT '订单编号',
  `status` varchar(255) NULL COMMENT '拦截状态: IN_PROGRESS拦截中【等待拦截】、SUCCEEDED拦截成功、FAILED拦截失败、CANCELED已取消',
  `order_goods_count` int(11) NULL COMMENT '拦截商品数量',
  `deliver_goods_count` int(11) NULL COMMENT '实际发货商品数量',
  `company_id` bigint(20) NULL COMMENT '拦截订单所属公司ID',
  `order_deliver_id` bigint(20) NULL COMMENT '发货单ID',
  `order_deliver_no` varchar(255) NULL COMMENT '发货单编号',
  `create_time` datetime NULL COMMENT '创建时间',
  `update_time` datetime NULL COMMENT '更新时间',
  `create_user_id` bigint(20) NULL COMMENT '创建人ID',
  `create_user_name` varchar(64) NULL COMMENT '创建人',
  `update_user_id` bigint(20) NULL COMMENT '更新人ID',
  `update_user_name` varchar(64) NULL COMMENT '更新人',
  PRIMARY KEY (`id`),
  KEY `idx_order` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='订单拦截表'
;

CREATE TABLE `demeter_order_intercept_item` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `item_intercept_no` varchar(255) NULL COMMENT '拦截子单号',
  `intercept_id` bigint(20) NULL COMMENT '拦截单ID',
  `intercept_no` varchar(255) NULL COMMENT '拦截单号',
  `order_item_id` bigint(20) NULL COMMENT '订单明细ID',
  `order_item_no` varchar(255) NULL COMMENT '订单明细编号',
  `goods_id` bigint(20) NULL COMMENT '商品ID',
  `goods_name` varchar(255) NULL COMMENT '商品名称',
  `order_goods_count` int(11) NULL COMMENT '拦截商品数量',
  `deliver_goods_count` int(11) NULL COMMENT '实际发货商品数量',
  `order_deliver_item_id` bigint(20) NULL COMMENT '发货单明细ID',
  `status` varchar(255) NULL COMMENT '拦截状态: IN_PROGRESS拦截中【等待拦截】、SUCCEEDED拦截成功、FAILED拦截失败、CANCELED已取消',
  `create_time` datetime NULL COMMENT '创建时间',
  `update_time` datetime NULL COMMENT '更新时间',
  `create_user_id` bigint(20) NULL COMMENT '创建人ID',
  `create_user_name` varchar(64) NULL COMMENT '创建人',
  `update_user_id` bigint(20) NULL COMMENT '更新人ID',
  `update_user_name` varchar(64) NULL COMMENT '更新人',
  `order_id` bigint(20) NULL COMMENT '订单ID',
  `order_no` varchar(255) NULL COMMENT '订单号',
  PRIMARY KEY (`id`),
  KEY `idx_order_item` (`order_item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='订单拦截明细表'
;

CREATE TABLE `demeter_order_item` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` bigint(20) NOT NULL COMMENT '订单ID',
  `order_no` varchar(64) NOT NULL COMMENT '订单编号',
  `order_item_no` varchar(64) NOT NULL COMMENT '订单明细编号',
  `goods_id` bigint(20) NOT NULL COMMENT '订单商品ID',
  `company_id` bigint(20) NOT NULL COMMENT '订单所属公司ID',
  `snapshot_version` varchar(64) NULL COMMENT '商品快照版本号',
  `sku_code` varchar(32) NULL COMMENT '商品sku编码',
  `baby_name` varchar(128) NULL COMMENT '宝贝名称',
  `goods_name` varchar(128) NOT NULL COMMENT '商品名称',
  `goods_count` int(11) NOT NULL DEFAULT 0 COMMENT '购买商品数量',
  `status` varchar(32) NOT NULL COMMENT '订单明细状态',
  `discount_money` decimal(8,2) NOT NULL DEFAULT 0.00 COMMENT '优惠分摊金额',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后修改时间',
  `order_deliver_id` bigint(20) NULL COMMENT '发货单id',
  `order_deliver_no` varchar(64) NULL COMMENT '发货单编号',
  `attach_url` varchar(256) NULL COMMENT '商品图片地址',
  `unit` varchar(16) NULL COMMENT '单位',
  `specification` varchar(16) NULL COMMENT '规格',
  `standard_price` decimal(8,2) NULL COMMENT '购买商品单价',
  `payable_amount` decimal(12,2) NULL COMMENT '商品应付金额',
  `payment_amount` decimal(12,2) NULL COMMENT '商品实付金额',
  `activity_price` decimal(8,2) NULL COMMENT '单一商品活动价',
  `actual_shipment_weight` decimal(12,2) NULL COMMENT '实际发货总重量',
  `shipped_qty` decimal(12,2) NULL COMMENT '实际发货数量',
  `estimate_deliver_date` datetime NULL COMMENT '预计送达时间',
  `unit_volume` decimal(8,2) NULL COMMENT '单位体积',
  `net_weight` decimal(8,2) NULL COMMENT '净重',
  `gross_weight` decimal(8,2) NULL COMMENT '毛重',
  `settlement_type` varchar(32) NULL COMMENT '结算类型',
  `unit_price_catty` decimal(8,2) NULL COMMENT '每斤单价',
  `standard_unit_price_catty` decimal(8,2) NULL COMMENT '标准每斤单价',
  `estimate_weight` decimal(12,2) NULL COMMENT '预计斤数',
  `estimate_amount` decimal(12,2) NULL COMMENT '预计金额',
  `real_weight` decimal(12,2) NULL COMMENT '实际斤数',
  `real_amount` decimal(12,2) NULL COMMENT '实际金额',
  `real_count` decimal(12,2) NULL COMMENT '实际购买商品数量',
  `real_unit_price` decimal(8,2) NULL COMMENT '实际采购单价',
  `complete_remarks` varchar(512) NULL COMMENT '完成订单备注',
  `complete_attach_urls` varchar(1024) NULL COMMENT '完成订单备注图片',
  `statement_date` date NULL COMMENT '订单归属日期',
  `shipping_amount` decimal(8,2) NULL COMMENT '运费',
  `service_amount` decimal(8,2) NULL COMMENT '服务费',
  `unit_price_service` decimal(8,2) NULL COMMENT '服务费单价',
  `customer_remarks` varchar(512) NULL COMMENT '下单客户备注',
  `stock_id` bigint(20) NULL COMMENT '订单所属仓库id',
  `stock_name` varchar(16) NULL COMMENT '订单所属仓库名称',
  `supplier_id` bigint(20) NULL COMMENT '供应商id',
  `purchase_stock_id` bigint(20) NULL COMMENT '订单采购仓库id',
  `system_coupon_user_id` bigint(20) NULL COMMENT '优惠卷id',
  `discount_rate` decimal(9,8) NULL COMMENT '折扣率',
  `seller_id` bigint(20) NULL COMMENT '卖家id',
  `seller_name` varchar(100) NULL COMMENT '卖家名称',
  `seller_type` varchar(32) NULL COMMENT '卖家类型',
  `in_the_promotion` tinyint(4) NULL COMMENT '是否促销活动中下单',
  `in_the_diff_city_diff_price` tinyint(4) NULL COMMENT '是否千城千价中下单',
  `in_the_ladder_price` tinyint(4) NULL COMMENT '是否参与阶梯价',
  `back_category_id` bigint(20) NULL COMMENT '后台所属类目',
  `commission_rate` decimal(5,2) NULL COMMENT '平台抽佣比例',
  `supply_batch_id` int(11) NULL COMMENT '调拨批次id',
  `supply_batch_name` varchar(64) NULL COMMENT '送货时效name',
  `kpi_statement_date` date NULL COMMENT '订单业绩归属日期',
  `ext_info` text NULL COMMENT '扩展信息',
  `spu_id` bigint(20) NULL COMMENT 'spuId',
  `business_id` bigint(20) NULL COMMENT '业务板块ID',
  `purchase_user_id` bigint(20) NULL COMMENT '供货经办人id',
  PRIMARY KEY (`id`),
  KEY `company_id` (`company_id`, `statement_date`, `status`),
  KEY `idx_distribute_query` (`company_id`, `stock_id`, `estimate_deliver_date`),
  KEY `idx_order_deliver_id` (`order_deliver_id`),
  KEY `idx_order_deliver_no` (`order_deliver_no`),
  KEY `idx_order_id` (`order_id`),
  UNIQUE KEY `idx_order_id_goods_id` (`order_id`, `goods_id`),
  KEY `idx_order_no` (`order_no`),
  KEY `idx_seller_statement_date` (`company_id`, `seller_id`, `statement_date`, `status`, `sku_code`),
  KEY `idx_skucode_supplierid_companyid_commissionrate` (`sku_code`, `supplier_id`, `company_id`, `commission_rate`),
  KEY `idx_statement_date` (`statement_date`, `goods_id`),
  UNIQUE KEY `order_item_no` (`order_item_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='订单明细表'
;

CREATE TABLE `demeter_order_item_activity` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_id` bigint(20) NOT NULL COMMENT '订单ID',
  `order_item_id` bigint(20) NOT NULL COMMENT '订单明细id',
  `activity_goods_item_id` bigint(20) NULL COMMENT '活动明细ID',
  `activity_goods_snapshot_version` varchar(64) NULL COMMENT '活动快照版本号',
  `activity_id` bigint(20) NULL COMMENT '活动ID',
  `goods_id` bigint(20) NULL COMMENT '商品ID',
