CREATE TABLE `demeter_order_item_purchase_requirement` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `purchase_order_id` bigint(20) NULL COMMENT '采购单ID',
  `order_id` bigint(20) NOT NULL COMMENT '订单ID',
  `order_no` varchar(64) NOT NULL COMMENT '订单编号',
  `order_item_id` bigint(20) NOT NULL COMMENT '订单明细ID',
  `goods_id` bigint(20) NOT NULL COMMENT '订单商品ID',
  `company_id` bigint(20) NOT NULL COMMENT '订单所属公司ID',
  `sku_code` varchar(32) NOT NULL COMMENT '商品sku编码',
  `baby_name` varchar(128) NULL COMMENT '宝贝名称',
  `goods_name` varchar(128) NULL COMMENT '商品名称',
  `goods_count` int(11) NULL COMMENT '需求商品数量',
  `goods_weight` decimal(10,2) NULL COMMENT '需求商品重量',
  `gross_weight` decimal(8,2) NULL COMMENT '毛重',
  `attach_url` varchar(512) NULL COMMENT '商品图片地址',
  `purchase_unit` varchar(16) NULL COMMENT '采购单位',
  `settle_unit` varchar(16) NULL COMMENT '结算单位',
  `specification` varchar(16) NULL COMMENT '规格',
  `estimate_purchase_price` decimal(10,2) NULL COMMENT '预计采购价格',
  `purchase_user_id` bigint(20) NULL COMMENT '采购员ID',
  `purchase_user_name` varchar(32) NULL COMMENT '采购员名字',
  `back_category_id` bigint(20) NULL COMMENT '后台所属类目',
  `back_category_name` varchar(50) NULL COMMENT '后台所属类目名字',
  `require_date` datetime NOT NULL COMMENT '需求日期',
  `activity_price` decimal(10,2) NULL COMMENT '销售价格',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后修改时间',
  `settlement_type` varchar(32) NULL COMMENT '结算类型',
  `customer_remarks` varchar(512) NULL COMMENT '下单客户备注',
  `status` varchar(32) NULL COMMENT '采购需求状态',
  `real_purchase_user_id` bigint(20) NULL COMMENT '实际采购员ID',
  `real_purchase_user_name` varchar(32) NULL COMMENT '实际采购员名字',
  `purchased_count` decimal(8,2) NULL COMMENT '已采购数量',
  `purchased_weight` decimal(10,2) NULL COMMENT '已采购重量',
  `purchase_price` decimal(10,2) NULL COMMENT '采购价格',
  `purchase_price_unit` decimal(10,2) NULL COMMENT '采购单价',
  `order_customer_type` varchar(32) NULL COMMENT '订单客户类型:普通、大客户',
  `stock_id` bigint(20) NULL COMMENT '订单所属仓库id',
  `stock_name` varchar(16) NULL COMMENT '订单所属仓库名称',
  `purchase_stock_id` bigint(20) NULL COMMENT '订单采购仓库id',
  `supplier_id` bigint(20) NULL COMMENT '供应商id',
  `seller_id` bigint(20) NULL COMMENT '卖家id',
  `seller_name` varchar(100) NULL COMMENT '卖家名称',
  `seller_type` varchar(32) NULL COMMENT '卖家类型',
  `activity_type` varchar(32) NULL COMMENT '活动类型',
  `supply_batch_id` int(11) NULL COMMENT '供货批次id',
  `supply_batch_name` varchar(64) NULL COMMENT '供货批次名称',
  `spu_id` bigint(20) NULL COMMENT 'spuId',
  PRIMARY KEY (`id`),
  KEY `idx_company_requirdate_ordercustomertype_purchaseuser` (`company_id`, `require_date`, `order_customer_type`, `purchase_user_id`),
  KEY `idx_orderId_status` (`order_id`, `status`),
  KEY `idx_orderItemId_status` (`order_item_id`, `status`),
  KEY `idx_purchaseuser_requirdate_ordercustomertype_company` (`purchase_user_id`, `require_date`, `order_customer_type`, `company_id`),
  KEY `idx_requirdate_company_ordercustomertype_purchaseuser` (`require_date`, `company_id`, `order_customer_type`, `purchase_user_id`, `goods_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='订单明细采购需求表'
;

CREATE TABLE `demeter_order_item_purchase_requirement_job_adjustment` (
