  `company_id` bigint(20) NOT NULL COMMENT '企业id',
  `store_id` bigint(20) NOT NULL COMMENT '店铺id',
  `store_type_code` varchar(50) NOT NULL COMMENT '店铺类型code',
  `store_name` varchar(50) NOT NULL COMMENT '店铺name',
  `standard_limit_amount` decimal(10,2) NOT NULL COMMENT '标准压单金额',
  `order_limit` decimal(10,2) NOT NULL COMMENT '订单真实压单金额',
  `enabled` bit(1) NOT NULL DEFAULT 'b\'1\'' COMMENT '启用禁用',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_user_id` bigint(20) NOT NULL COMMENT '创建人id',
  `create_user_name` varchar(50) NOT NULL COMMENT '创建人name',
  `update_user_id` bigint(20) NOT NULL COMMENT '更新人id',
  `update_user_name` varchar(255) NOT NULL COMMENT '更新人name',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  `note` varchar(255) NOT NULL COMMENT '备注',
  `approve_code` varchar(200) NULL COMMENT '审批code',
  `approve_user_id` bigint(20) NULL COMMENT '审批人Id',
  `approve_user_name` varchar(50) NULL COMMENT '审批人',
  PRIMARY KEY (`id`),
  KEY `idx` (`store_id`, `store_type_code`),
  UNIQUE KEY `uk` (`store_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

