CREATE TABLE `demeter_order_stage_info` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `order_id` bigint(20) NOT NULL COMMENT '订单ID',
  `order_no` varchar(60) NOT NULL COMMENT '订单编号',
  `stage_id` bigint(20) NOT NULL COMMENT '驿站ID',
  `stage_name` varchar(60) NOT NULL COMMENT '驿站名称',
  `store_id` bigint(20) NOT NULL COMMENT '门店ID',
  `store_province_id` bigint(20) NULL COMMENT '门店省ID',
  `store_province_name` varchar(60) NULL COMMENT '门店省名称',
  `store_city_id` bigint(20) NULL COMMENT '门店市ID',
  `store_city_name` varchar(60) NULL COMMENT '门店市名称',
  `store_county_id` bigint(20) NULL COMMENT '门店区ID',
  `store_county_name` varchar(60) NULL COMMENT '收货区名称',
  `store_street_id` bigint(20) NULL COMMENT '街道ID',
  `store_street_name` varchar(60) NULL COMMENT '收货街道名称',
  `store_address` varchar(250) NULL COMMENT '门店地址',
  `store_link_man` varchar(60) NULL COMMENT '门店联系人',
  `store_link_phone` varchar(60) NULL COMMENT '门店联系电话',
  `pickup_status` int(11) NOT NULL COMMENT '提货状态 0未提货 1已提货 3无需提货',
  `delivery_type` int(11) NOT NULL COMMENT '送货方式 1驿站自提 0送货到店',
  `stage_pickup_time` varchar(40) NULL COMMENT '驿站提货时间',
  `store_latitude` decimal(12,8) NULL COMMENT '门店纬度',
  `store_longitude` decimal(12,8) NULL COMMENT '门店经度',
  `finish_pickup_time` datetime NULL COMMENT '完成提货时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `demeter_order_stage_info_order_id_IDX` (`order_id`)
