CREATE TABLE `demeter_period_customer_approve_recode` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `center_stock` varchar(50) NOT NULL COMMENT '中心仓',
  `store_id` bigint(20) NOT NULL COMMENT '店铺ID',
  `store_name` varchar(50) NOT NULL COMMENT '店铺名称',
  `seller_id` bigint(20) NOT NULL COMMENT '商家ID',
  `seller_name` varchar(50) NOT NULL COMMENT '商家名称',
  `transfer_date` date NOT NULL COMMENT '转账日期',
  `transfer_amount` decimal(10,2) NOT NULL COMMENT '转账金额',
  `offset_cost_amount` decimal(10,2) NOT NULL COMMENT '冲抵费用金额',
  `verification_amount` decimal(10,2) NOT NULL COMMENT '本次核销金额',
  `period_year` int(11) NOT NULL COMMENT '账期归属年',
  `billing_period_no` int(11) NOT NULL COMMENT '账期',
  `period_type` varchar(50) NOT NULL COMMENT '账期类型',
  `approval_status` varchar(50) NOT NULL COMMENT '审批状态',
  `pass_time` datetime NOT NULL COMMENT '通过时间',
  `instance_code` varchar(200) NOT NULL COMMENT '实体code',
  `discount_rate` decimal(10,6) NULL COMMENT '折扣率',
  `ext_info` longtext NULL COMMENT '扩展信息',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk` (`store_id`, `seller_id`, `billing_period_no`, `period_type`, `period_year`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='账期折扣金审批记录'
;

CREATE TABLE `demeter_period_customer_order_ext` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `period_biz_type` varchar(50) NOT NULL DEFAULT 'COMPANY_PERIOD' COMMENT '账期类型',
  `company_id` bigint(20) NOT NULL COMMENT '归属企业id',
  `order_id` bigint(20) NOT NULL COMMENT '订单id',
  `order_no` varchar(68) NOT NULL COMMENT '订单No',
  `seller_id` bigint(20) NOT NULL COMMENT '卖家id',
  `store_id` bigint(20) NOT NULL COMMENT 'storeID',
  `ep_company_id` bigint(20) NOT NULL COMMENT '企业id',
  `statement_date` date NOT NULL COMMENT '订单的归属日期',
  `period_year` int(11) NOT NULL COMMENT '账期归属年',
  `billing_period_type` varchar(50) NOT NULL COMMENT '账期类型',
  `period_no` varchar(32) NOT NULL COMMENT '账期序数',
  `billing_period_id` bigint(20) NOT NULL COMMENT '账期的记录id',
  `pay_start` date NOT NULL COMMENT '支付开始时间',
  `last_pay_time` date NOT NULL COMMENT '最受支付的时间',
  `payment_apply_serial_no` varchar(68) NULL COMMENT '支付申请单号',
  `pay_status` varchar(50) NOT NULL DEFAULT 'NOT_PAY' COMMENT '支付的状态',
  `estimate_delivery_date` date NOT NULL COMMENT '预计送达时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '支付时间',
  `ext_info` longtext NULL COMMENT '扩展信息',
  PRIMARY KEY (`id`),
  KEY `idx` (`company_id`, `pay_start`, `last_pay_time`, `pay_status`),
  KEY `idx_store_type_time` (`store_id`, `last_pay_time`),
  KEY `uk` (`order_id`),
  UNIQUE KEY `unq_idx_order` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='大账期订单扩展信息表'
;

CREATE TABLE `demeter_period_customer_order_pre_clearing` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
