CREATE TABLE `demeter_prepare_order` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `prepare_order_no` varchar(64) NOT NULL COMMENT '预订单编号',
  `order_id` bigint(20) NULL COMMENT '合单后对应订单id',
  `order_no` varchar(64) NULL COMMENT '合单后对应订单号',
  `customer_id` bigint(20) NOT NULL COMMENT '下单人ID',
  `customer_name` varchar(32) NULL COMMENT '下单人姓名',
  `customer_store_id` bigint(20) NULL COMMENT '下单人关联店铺ID',
  `customer_mobile` varchar(32) NULL COMMENT '下单人联系电话',
  `company_id` bigint(20) NOT NULL COMMENT '订单所属公司ID',
  `consignee_realname` varchar(32) NOT NULL COMMENT '收货人姓名',
  `consignee_telphone` varchar(32) NOT NULL COMMENT '收货人联系电话',
  `province_id` bigint(20) NOT NULL COMMENT '收货省',
  `city_id` bigint(20) NOT NULL COMMENT '收货市',
  `district_id` bigint(20) NOT NULL COMMENT '收货区',
  `address` varchar(250) NOT NULL COMMENT '收货地址',
  `order_money` decimal(8,2) NOT NULL COMMENT '订单金额',
  `discount_money` decimal(8,2) NOT NULL DEFAULT 0.00 COMMENT '优惠金额',
  `shipping_money` decimal(8,2) NOT NULL DEFAULT 0.00 COMMENT '运费金额',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status` varchar(32) NOT NULL COMMENT '订单状态',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后修改时间',
  `remark` varchar(256) NULL COMMENT '订单备注',
  `province_name` varchar(50) NULL COMMENT '收货省名称',
  `city_name` varchar(50) NULL COMMENT '收货市名称',
  `county_name` varchar(50) NULL COMMENT '收货区名称',
  `payable_amount` decimal(8,2) NULL COMMENT '应付金额',
  `payment_amount` decimal(8,2) NULL COMMENT '实付金额',
  `pay_serial_number` varchar(64) NULL COMMENT '付款流水号',
  `deleted` tinyint(4) NOT NULL DEFAULT 0 COMMENT '删除 1是 0否',
  `invite_store_id` bigint(20) NULL COMMENT '下单人的上级合伙人的店铺id',
