  `standard_price` decimal(8,2) NULL COMMENT '购买商品单价',
  `payable_amount` decimal(8,2) NULL COMMENT '商品应付金额',
  `payment_amount` decimal(8,2) NULL COMMENT '商品实付金额',
  `activity_price` decimal(8,2) NULL COMMENT '单一商品活动价',
  `actual_shipment_weight` decimal(8,2) NULL COMMENT '实际发货总重量',
  `shipped_qty` decimal(8,2) NULL COMMENT '实际发货数量',
  `unit_volume` decimal(8,2) NULL COMMENT '单位体积',
  `net_weight` decimal(8,2) NULL COMMENT '净重',
  `gross_weight` decimal(8,2) NULL COMMENT '毛重',
  `settlement_type` varchar(32) NULL COMMENT '结算类型',
  `unit_price_catty` decimal(8,2) NULL COMMENT '每斤单价',
  `estimate_weight` decimal(8,2) NULL COMMENT '预计斤数',
  `estimate_amount` decimal(8,2) NULL COMMENT '预计金额',
  `real_weight` decimal(8,2) NULL COMMENT '实际斤数',
  `real_amount` decimal(8,2) NULL COMMENT '实际金额',
  `real_count` decimal(8,2) NULL COMMENT '实际购买商品数量',
  `real_unit_price` decimal(8,2) NULL COMMENT '实际采购单价',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_order_no` (`order_no`),
  KEY `idx_prepare_order_id` (`prepare_order_id`),
  KEY `idx_prepare_order_no` (`prepare_order_no`),
  UNIQUE KEY `idx_prepare_orderitem_no` (`prepare_order_item_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='预订单明细表'
;

CREATE TABLE `demeter_proxy_pay_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `company_id` bigint(20) NOT NULL COMMENT '企业ID',
  `order_id` bigint(20) NOT NULL COMMENT '订单ID',
  `order_no` varchar(64) NOT NULL COMMENT '订单号',
  `order_store_id` bigint(20) NOT NULL COMMENT '下单店铺ID',
  `order_user_id` bigint(20) NOT NULL COMMENT '下单用户ID',
  `pay_store_id` bigint(20) NOT NULL COMMENT '支付店铺ID',
  `pay_user_id` bigint(20) NOT NULL COMMENT '支付用户ID',
  `statement_date` date NOT NULL COMMENT '归属日期',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `column_name` varchar(11) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `statement_date_idx` (`company_id`, `statement_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='代付订单记录'
;

CREATE TABLE `demeter_rebate_discount_store_config` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `store_id` bigint(20) NOT NULL COMMENT '店铺id',
  `seller_issue_rate` decimal(11,2) NOT NULL COMMENT '卖家承担比例',
  `rebate_rate` decimal(2,2) NOT NULL COMMENT '返点比例',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_user_id` bigint(20) NOT NULL COMMENT '创建人id
',
  `create_user_name` varchar(50) NOT NULL,
  `update_time` datetime NOT NULL,
  `update_user_id` bigint(20) NOT NULL,
  `update_user_name` varchar(50) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_store_id` (`store_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='门店维度的返点优惠配置表'
;

CREATE TABLE `demeter_refund_order` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `refund_order_no` varchar(64) NOT NULL DEFAULT '' COMMENT '退款单号',
  `after_sale_no` varchar(64) NOT NULL DEFAULT '' COMMENT '售后单号',
  `order_id` bigint(20) NOT NULL COMMENT '订单ID',
  `order_no` varchar(64) NOT NULL DEFAULT '' COMMENT '订单号',
  `order_item_id` varchar(1024) NOT NULL COMMENT '订单项ID(冗余)',
  `temp_order_clearing_id` bigint(20) NOT NULL COMMENT '临时清分ID',
  `refund_amount` decimal(8,2) NULL COMMENT '退款金额',
  `order_payment_no` varchar(64) NULL COMMENT '自身订单付款单编号',
  `payment_serial_number` varchar(64) NOT NULL DEFAULT '' COMMENT '支付流水号',
  `refund_order_status` varchar(64) NOT NULL COMMENT '退款单状态',
  `refund_order_origin_type` varchar(64) NOT NULL COMMENT '退款单来源的类型',
  `origin_order_payment_no` varchar(64) NOT NULL DEFAULT '' COMMENT '原始订单付款单编号',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `create_time` (`create_time`),
  KEY `idx_payment_serial_number` (`payment_serial_number`),
  KEY `order_id_index` (`order_id`),
  KEY `order_no_index` (`order_no`),
  UNIQUE KEY `order_payment_no_unique` (`order_payment_no`),
  KEY `refund_order_no_index` (`refund_order_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='退款单'
;

CREATE TABLE `demeter_service_fee_store_config` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `company_id` bigint(20) NOT NULL COMMENT '企业ID',
  `store_id` bigint(20) NULL COMMENT '门店ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `province_id` bigint(20) NULL COMMENT '省区ID',
  `city_id` bigint(20) NULL COMMENT '市区ID',
  `district_id` bigint(20) NULL COMMENT '区县ID',
  `street_id` bigint(20) NULL COMMENT '街道ID',
  `include_type` varchar(64) NULL COMMENT 'INCLUDE:包含|EXCLUDE:排除',
  PRIMARY KEY (`id`),
  KEY `qry_idx` (`company_id`, `store_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_shopping_cart` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `goods_id` bigint(20) NOT NULL COMMENT '商品id',
  `goods_type` varchar(50) NULL COMMENT '商品',
  `company_id` bigint(20) NULL COMMENT '企业id',
  `user_id` bigint(20) NOT NULL COMMENT '用户id',
  `number` int(11) NOT NULL DEFAULT 0 COMMENT '数量',
  `init_price` decimal(12,3) NULL COMMENT '加入时单价(按斤或按件单价)',
  `goods_snapshot` text NULL COMMENT '加购时商品镜像',
  `deleted` int(11) NOT NULL DEFAULT 0 COMMENT '是否删除',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK_GOODS_USER_IDX` (`goods_id`, `user_id`),
  KEY `user_type` (`user_id`, `goods_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_sihang_merge_order` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `seller_id` bigint(20) NOT NULL COMMENT '卖家id',
  `estimate_delivery_data` datetime NOT NULL COMMENT '预计送达日期',
  `merged_payable_money` decimal(12,2) NOT NULL COMMENT '合并后的Payable金额',
  `merged_real_count` decimal(12,2) NOT NULL COMMENT '聚合的所有数量',
  `order_submit_id` bigint(20) NOT NULL COMMENT '订单提交批次id',
  `merge_order_no` varchar(68) NOT NULL COMMENT '合并后的订单No',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `ext` text NULL COMMENT '扩展字段',
  `store_id` bigint(20) NOT NULL,
  `store_name` varchar(68) NULL,
  PRIMARY KEY (`id`),
  KEY `NK_ORDER_NO` (`estimate_delivery_data`, `merge_order_no`),
  UNIQUE KEY `UK_SUBMIT_ID` (`order_submit_id`, `seller_id`, `estimate_delivery_data`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='sihang聚合订单'
;

CREATE TABLE `demeter_sihang_merge_order_item` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_submit_id` bigint(20) NOT NULL COMMENT '订单提交批次id',
  `merge_order_no` varchar(68) NOT NULL COMMENT '合并后的订单No',
  `merged_payable_money` decimal(12,2) NOT NULL COMMENT '合并后的金额',
  `merged_goods_count` decimal(12,2) NOT NULL COMMENT '合并后的金额',
  `goods_id` bigint(20) NOT NULL COMMENT '预计送达日期',
  `goods_name` varchar(65) NOT NULL COMMENT '商品名',
  `ext` text NULL COMMENT '合并的orderItemId',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `sku_code` varchar(68) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `UK_ORDER_NO` (`merge_order_no`, `goods_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='sihang聚合订单Item'
;

CREATE TABLE `demeter_store_debt_order` (
  `id` bigint(11) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `customer_store_id` bigint(11) NOT NULL COMMENT '门店id',
  `order_id` bigint(11) NOT NULL COMMENT '门店id',
  `origin_pay_status` varchar(68) NOT NULL COMMENT '原始订单支付状态',
  `payed` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否支付',
  `make_up_money` decimal(12,2) NOT NULL COMMENT '需要补的钱',
  `statement_data` date NOT NULL COMMENT '归属日期',
  `pay_confirm` tinyint(1) NOT NULL COMMENT '是否确认应付',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `NK_CUST` (`customer_store_id`, `payed`, `statement_data`),
  UNIQUE KEY `UK_ORDER` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_sys_config` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `type` varchar(32) NOT NULL COMMENT '类型',
  `config_key` varchar(64) NOT NULL COMMENT '键',
  `config_value` text NOT NULL COMMENT '值',
  `sort` int(11) NOT NULL COMMENT '排序',
  `status` int(11) NOT NULL COMMENT '状态',
  `description` varchar(2048) NOT NULL COMMENT '描述',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_type_config_key` (`type`, `config_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='系统数据配置表'
;

CREATE TABLE `demeter_sys_config_company` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `company_id` bigint(20) NOT NULL COMMENT '公司ID',
  `type` varchar(32) NOT NULL COMMENT '类型',
  `config_key` varchar(64) NOT NULL COMMENT '键',
  `config_value` text NOT NULL COMMENT '值',
  `sort` int(11) NOT NULL COMMENT '排序',
  `status` int(11) NOT NULL COMMENT '状态',
  `description` varchar(2048) NOT NULL COMMENT '描述',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_company_type_config_key` (`company_id`, `type`, `config_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='公司级系统数据配置表'
;

CREATE TABLE `store_goods_buy_count_data` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` bigint(20) NOT NULL COMMENT '企业ID',
  `goods_id` bigint(20) NOT NULL COMMENT '商品id',
  `goods_name` varchar(128) NOT NULL COMMENT '商品名称',
  `back_category_id` bigint(20) NULL COMMENT '后台四级类目ID',
  `settlement_type` varchar(32) NULL COMMENT '结算类型',
  `store_id` bigint(20) NOT NULL COMMENT '门店id',
  `buy_count` int(11) NOT NULL COMMENT '最近90天购买次数',
  `last_price` decimal(8,2) NOT NULL COMMENT '最近单价',
  `last_statement_date` date NOT NULL COMMENT '最近下单的归属日期',
  `last_buy_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最近下单时间',
  `last_order_item_id` bigint(20) NOT NULL COMMENT '最后一次下单的明细ID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后修改时间',
  `sort_no` int(11) NOT NULL DEFAULT 1 COMMENT '算法同步的排序号，优先级最高',
  `opportunity_type` varchar(100) NULL COMMENT '机会类型',
  `recommend_reason` varchar(500) NULL COMMENT '推荐原因',
  PRIMARY KEY (`id`),
  KEY `idx_com_store_category_date` (`company_id`, `store_id`, `back_category_id`, `last_statement_date`),
  KEY `idx_com_store_date` (`company_id`, `store_id`, `last_statement_date`),
  KEY `idx_store_company_goods` (`store_id`, `company_id`, `goods_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;
